import { Metadata } from './metadata'
import { Link } from './link'
import { constructObjectsInArray } from './util/constructInArray'
import { FpBlobData } from './blobType'

export class Publication {
  // TODO GetToC (Rename Spine?)

  // TODO Possibly: GetSourceURI, GetHrefRelativeToManifest,
  //  IsInternalHref, SearchLinksByRel, Spine/GetSpine

  // const selfLink
  // const baseURI

  '@context'?: object
  metadata: Metadata
  links: Link[]
  readingOrder: Link[]
  resources?: Link[]
  toc?: Link[]

  // EPUB Extensions
  pageList?: Link[]
  landmarks?: Link[]
  loa?: Link[]
  loi?: Link[]
  lot?: Link[]
  lov?: Link[]
  blobData?: FpBlobData

  selfLink: Link;

  // Any other extensions
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any

  public getAsAbsoluteURL(href: string): URL {
    let newHref = href
    if (newHref[0] === '/') {
      newHref = newHref.slice(1)
    }

    return new URL(newHref, this.selfLink.href)
  }

  public getBaseURI(): string {
    // NOTE I'm not sure if we will have SourceURI ever
    // if( this.sourceURI ) {
    //     href = new URL('./', this.sourceURI).toString();
    // }

    // NOTE The following produces an error
    // return new URL('./', selfLink.href).toString();

    if (!this.baseURI) {
      this.baseURI = this.selfLink.href.slice(
        0,
        this.selfLink.href.lastIndexOf('/') + 1,
      )
    }
    // TODO Should not be using a base URI at all
    return this.baseURI
  }

  get spine(): Link[] {
    return this.readingOrder
  }

  public getCover(): Link | undefined {
    if (this.resources) {
      return Publication.SearchForLinkInCollectionByRel(this.resources, 'cover')
    }
  }

  private searchLinkByRel(rel: string): Link | undefined {
    if (this.readingOrder) {
      const target = Publication.SearchForLinkInCollectionByRel(
        this.readingOrder,
        rel,
      )
      if (target) {
        return target
      }
    }

    if (this.resources) {
      const target = Publication.SearchForLinkInCollectionByRel(
        this.resources,
        rel,
      )
      if (target) {
        return target
      }
    }

    if (this.links) {
      const target = Publication.SearchForLinkInCollectionByRel(this.links, rel)
      if (target) {
        return target
      }
    }

    return undefined
  }

  public findSpineItemIndexByHref(href: string): number {
    return this.readingOrder.findIndex((element) => element.href === href)
  }

  static SearchForLinkInCollectionByRel(
    collection: Link[],
    rel: string,
  ): Link | undefined {
    return collection.find((element) => {
      return element.rel && element.rel.includes(rel)
    })
  }

  /**
   * Parse a manifest into a publication.
   * @param {Object} object JSON-like object
   * @param {string} [baseURL=null] Optional base URL (self link href)
   * @throws {Error} Argument object must be an object.
   */
  static async Parse(
    object: string,
    baseURL: string | null = null,
  ): Promise<Publication> {
    const publication = new Publication()

    /* NOTE The definitions of which property are Extensions are unclear
     *  I'm unclear as to why the following was dictated [Context, Metadata, Links, ReadingOrder, Resources] to
     *  to be in Core, and everything else in EPUB Extension
     *  https://github.com/evidentpoint/r2-webpub-model-js/blob/master/src/models/publication/publication.ts
     *  -
     *  whereas the following has very different roles for them
     *  https://readium.org/webpub-manifest/roles.html
     */

    if (typeof object !== 'object') {
      throw new Error('Argument object must be an object.')
    }

    // Make new object to manipulate
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const manifest: any = Object.assign({}, object)

    // @Context
    if (manifest['@context']) {
      publication['@context'] = manifest['@context']
    }
    delete manifest['@context']

    // Metadata, Required
    publication.metadata = Metadata.Parse(manifest.metadata)
    delete manifest.metadata

    // Links, Required(could be null)
    publication.links = constructObjectsInArray(manifest.links, Link.Parse)
    delete manifest.links

    // If there is no 'self' link, it's technically a malformed manifest...but we'll roll with it
    let selfLink = this.SearchForLinkInCollectionByRel(
      publication.links,
      'self',
    )
    if (!selfLink) {
      selfLink = new Link()
      selfLink.rel = ['self']
    }

    // Override the 'self' link's href if there is a baseURL
    if (baseURL) {
      selfLink.href = baseURL
    }

    if (!selfLink.href) {
      throw new Error('Miss self link or base url.')
    }

    if (manifest['fp:blobData']) {
      publication.blobData = manifest['fp:blobData']
    }

    publication.selfLink = selfLink

    // Then if there is no 'self' link in the manifest, push our baseURL link into the model
    if (!this.SearchForLinkInCollectionByRel(publication.links, 'self')) {
      publication.links.push(publication.selfLink)
    }

    // Reading Order, Required
    publication.readingOrder = constructObjectsInArray(
      manifest.readingOrder,
      Link.Parse,
    )
    delete manifest.readingOrder

    // Resources
    if (manifest.resources) {
      publication.resources = constructObjectsInArray(
        manifest.resources,
        Link.Parse,
      )
    }
    delete manifest.resources

    // Define ToC at the end, since it requires readingOrder and Resources
    //  to exists if a ToC entry doesn't exist in the manifest

    // If a TOC exists, simply parse it and return
    if (manifest.toc) {
      publication.toc = constructObjectsInArray(manifest.toc, Link.Parse)
    } else {
      // eslint-disable-next-line @typescript-eslint/no-use-before-define
      publication.toc = await defineToc(publication)
    }
    delete manifest.toc

    // Finally parse all extension entries as SubCollection
    // eslint-disable-next-line @typescript-eslint/no-use-before-define
    const out = parseAsSubcollections(manifest)
    Object.assign(publication, out)

    return publication
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const parseAsSubcollectionObject = (json: any): any => {
  const subcollectionJSON = Object.assign({}, json)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const subcollection: any = {}

  if (!subcollectionJSON.metadata || !subcollectionJSON.links) {
    return subcollectionJSON
  }

  subcollection.metadata = subcollectionJSON.metadata
  delete subcollectionJSON.metadata

  subcollection.links = constructObjectsInArray(
    subcollectionJSON.links,
    Link.Parse,
  )
  delete subcollectionJSON.links

  // eslint-disable-next-line @typescript-eslint/no-use-before-define
  Object.assign(subcollection, parseAsSubcollections(subcollectionJSON))

  return subcollection
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
const parseAsSubcollections = (json: any): any => {
  const otherProperties = Object.assign({}, json)

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const otherCollections: any = {}

  // All others treated as a sub-collection
  Object.keys(otherProperties).forEach((property) => {
    // Set the sub collection
    const collection = otherProperties[property]

    if (Array.isArray(collection)) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const newCollection: any[] = []

      // If it's an array, iterate through the array
      collection.forEach((element) => {
        // Figure out if it's a Link or not
        if (element.href) {
          // Treat as Link
          newCollection.push(Link.Parse(element))
        } else {
          // Treat as a Sub Collection object
          newCollection.push(parseAsSubcollectionObject(element))
        }
      })

      // Replace the original property with the Sub Collection
      otherCollections[property] = newCollection
    } else {
      // If not an Array, treat as a Sub Collection Object
      otherCollections[property] = parseAsSubcollectionObject(collection)
    }
  })

  return otherCollections
}

// Find the entry for contents if it exists
const findContentsInCollections = (collections: Link[][]): Link | undefined => {
  for (const collection of collections) {
    if (collection) {
      const link = Publication.SearchForLinkInCollectionByRel(
        collection,
        'contents',
      )
      if (link) {
        return link
      }
    }
  }
  return undefined
}

const defineToc = async (
  publication: Publication,
): Promise<Link[] | undefined> => {
  // TODO Guard against non-browser environment for now
  // eslint-disable-next-line no-undef
  if (typeof window == 'undefined') {
    // NOT IN BROWSER
    console.error('Not in browser environment')
    return undefined
  }

  // TODO deal with not in browser implementation

  const cols = [publication.readingOrder]
  if (publication.resources) {
    cols.push(publication.resources)
  }
  const contents = findContentsInCollections(cols)

  if (!contents) {
    // NOTE Really should throw an error or something
    console.error('Could not find Contents entry in manifest')
    return undefined
  }

  // TODO parse html/xhtml
  // https://www.w3.org/publishing/epub3/epub-packages.html#sec-package-nav

  // Fetch document
  const fetchDoc = await (
    await fetch(publication.getAsAbsoluteURL(contents.href).href)
  ).text()

  // Get the ToC Entry
  const parser = new DOMParser()
  const doc = parser.parseFromString(fetchDoc, 'text/html')
  const tocElement = doc.querySelector('[epub\\:type="toc"]')

  // NOTE We're ignoring the HTML Heading of the top node since I have no idea what to do with it

  // Grab the list of <li> in the toc node
  const nodes = tocElement?.lastElementChild?.children

  // eslint-disable-next-line @typescript-eslint/no-use-before-define
  return parseHTMLCollectionAsLinks(nodes)
}

// Parse node as a link object
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const parseHTMLCollectionAsLinks = (nodes: any): Link[] => {
  const result = []

  // https://stackoverflow.com/questions/22754315/for-loop-for-htmlcollection-elements
  for (let i = 0; i < nodes.length; i++) {
    // For each <li> node, get its children
    const nodeItems = nodes.item(i).children
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const output: any = {}

    // The first element should always be a <span> or <a>
    const item = nodeItems.item(0)

    // The title is the text of the tag
    output.title = item.innerHTML

    // Get the HREF if it's an anchor, or TODO
    if (item.tagName.toLocaleLowerCase() === 'a') {
      output.href = item.getAttribute('href')
    } else {
      // TODO Tag is SPAN, so no link should be present
      output.href = '#'
    }

    // Check for children and recursively parse
    if (nodeItems.length > 1) {
      output.children = parseHTMLCollectionAsLinks(nodeItems.item(1).children)
    }

    // Push the result parsed into a Link
    result.push(Link.Parse(output))
  }

  return result
}
