import { constructObjectsInArray } from './util/constructInArray'
import { LocalizedString } from './localized-string'
import { Link } from './link'

export class Subject {
  name: LocalizedString
  sortAs?: string
  code?: string
  scheme?: string
  links?: Link[]

  static Parse(object: object): Subject[] {
    if (Array.isArray(object)) {
      // If an array, parse all elements
      return constructObjectsInArray(object, Subject.ParseSubjectObject)
    }

    return [Subject.ParseSubjectObject(object)]
  }

  static ParseSubjectObject(object: object): Subject {
    const subject = new Subject()

    if (typeof object === 'string') {
      // If subject is a simple string
      subject.name = { '': object }
      // No more fields to parse
      return subject
    }

    // Otherwise, parse the Subject object

    Object.assign(subject, object)

    // Parse name as LocalizedString
    if (typeof subject.name === 'string') {
      subject.name = { '': subject.name }
    }

    if (subject.links) {
      subject.links = constructObjectsInArray(subject.links, Link.Parse)
    }

    return subject
  }
}
