import { Link } from './link'
import { LocalizedString } from './localized-string'
import { constructObjectsInArray } from './util/constructInArray'
import { normalizeStringToArray } from './util/normalizeStringToArray'

export class Contributor {
  name: LocalizedString
  identifier?: string
  sortAs?: string
  role?: string[]
  position?: number
  links?: Link[]

  /**
   * @param {object | string | string[] | object[]} contributorDescription
   * string - https://github.com/readium/webpub-manifest/blob/0976680e25852b8a4c4802a052ba750ab3e89284/schema/contributor.schema.json#L7
   * object - https://github.com/readium/webpub-manifest/blob/0976680e25852b8a4c4802a052ba750ab3e89284/schema/contributor.schema.json#L24
   * array of strings - https://github.com/readium/webpub-manifest/blob/0976680e25852b8a4c4802a052ba750ab3e89284/schema/contributor.schema.json#L10
   * array of objects - https://github.com/readium/webpub-manifest/blob/0976680e25852b8a4c4802a052ba750ab3e89284/schema/contributor.schema.json#L17
   * @returns {Contributor[]}
   */
  static Parse(
    contributorDescription: object | string | string[] | object[],
  ): Contributor[] {
    if (Array.isArray(contributorDescription)) {
      // If json is an array, initialize all elements as Contributor
      return constructObjectsInArray(
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        contributorDescription as any[],
        Contributor.ParseContributorObject,
      )
    }

    // Otherwise, proceed to parsing the full Contributor Object
    return [this.ParseContributorObject(contributorDescription)]
  }

  static ParseContributorObject(objectOrString: object | string): Contributor {
    const contributor = new Contributor()

    if (typeof objectOrString === 'string') {
      // If contributor is a simple string
      contributor.name = { '': objectOrString }
      // No more fields to parse
      return contributor
    }

    Object.assign(contributor, objectOrString)

    // Parse name as LocalizedString
    if (typeof contributor.name === 'string') {
      contributor.name = { '': contributor.name }
    }

    // Parse links as Links
    if (contributor.links) {
      contributor.links = constructObjectsInArray(contributor.links, Link.Parse)
    }

    if (contributor.role) {
      contributor.role = normalizeStringToArray(contributor.role)
    }

    return contributor
  }
}
