import { constructObjectsInArray } from './util/constructInArray'
import { normalizeStringToArray } from './util/normalizeStringToArray'
import { Properties } from './properties'

// TODO figure out URI templates

export class Link {
  href: string
  type?: string
  templated?: boolean
  title?: string
  // rel?: Relation[]
  rel?: string[]
  properties?: Properties
  height?: number
  width?: number
  bitrate?: number
  duration?: number
  language?: string[]
  alternate?: Link[]
  children?: Link[];

  // Any other extensions
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any

  static Parse(object: object): Link {
    const link = new Link()

    // Copy all properties over to the new object
    Object.assign(link, object)

    // Construct Properties
    if (link.properties) {
      link.properties = Properties.Parse(link.properties)
    }

    // Recursively parse Alternates as Links
    if (link.alternate) {
      link.alternate = constructObjectsInArray(link.alternate, Link.Parse)
    }

    // Recursively parse children as Links
    if (link.children) {
      link.children = constructObjectsInArray(link.children, Link.Parse)
    }

    if (link.rel) {
      link.rel = normalizeStringToArray(link.rel)
    }

    if (link.language) {
      link.language = normalizeStringToArray(link.language)
    }

    return link
  }
}
