/* eslint-disable @typescript-eslint/no-explicit-any */
export const constructObjectsInArray = (
  array: any[] | null,
  objectParser: Function,
): any[] => {
  const arr: any[] = []

  if (!array || !Array.isArray(array)) {
    return arr
  }

  array.forEach((element) => {
    arr.push(objectParser(element))
  })

  return arr
}
