import { Contributor } from '../contributor'
import { Subject } from '../subject'
import { LocalizedString } from '../localized-string'
import { Presentation } from '../presentation'
import { normalizeStringToArray } from '../util/normalizeStringToArray'

import type {
  BelongsTo,
  ManifestMetadataSourceObjectAnyFormat,
  PublicationMetadata,
  ReadingProgression,
  SupplementMetadata,
} from './types'
import { supplementFlowpubMetadataWithReadium2FormatMetadata } from './migration'

export class Metadata implements PublicationMetadata {
  identifier?: string
  title: LocalizedString
  subtitle?: LocalizedString
  modified?: Date
  published?: Date
  language?: string[]
  sortAs?: string
  author?: Contributor[]
  translator?: Contributor[]
  editor?: Contributor[]
  artist?: Contributor[]
  illustrator?: Contributor[]
  letterer?: Contributor[]
  penciler?: Contributor[]
  colorist?: Contributor[]
  inker?: Contributor[]
  narrator?: Contributor[]
  contributor?: Contributor[]
  publisher?: Contributor[]
  imprint?: Contributor[]
  subject?: Subject[]
  readingProgression?: ReadingProgression
  description?: string
  duration?: number
  numberOfPages?: number
  belongsTo?: BelongsTo
  presentation?: Presentation

  /**
   * Object - is a manifest.json:metadata deserialized
   *
   * @static
   * @param {object} object - should conform to JSON schema
   * main - https://github.com/readium/webpub-manifest/blob/master/schema/metadata.schema.json
   * extension - https://github.com/readium/webpub-manifest/blob/917c83e798e3eda42b3e9d0dc92f0fef31b16211/schema/extensions/epub/metadata.schema.json
   * @return {Metadata}
   * @memberof Metadata
   */
  static Parse(
    object: ManifestMetadataSourceObjectAnyFormat,
    supplementMetadata: SupplementMetadata<
      PublicationMetadata
    > = supplementFlowpubMetadataWithReadium2FormatMetadata,
  ): Metadata {
    const metadata: PublicationMetadata = new Metadata()

    Object.assign(metadata, object)

    if (typeof metadata.title === 'string') {
      metadata.title = { '': metadata.title }
    }

    if (typeof metadata.subtitle === 'string') {
      metadata.subtitle = { '': metadata.subtitle }
    }

    if (metadata.subject) {
      metadata.subject = Subject.Parse(metadata.subject)
    }

    // A list of all Contributor fields
    const contributorProperties = [
      'artist',
      'author',
      'translator',
      'editor',
      'illustrator',
      'letterer',
      'penciler',
      'colorist',
      'inker',
      'narrator',
      'contributor',
      'publisher',
      'imprint',
    ]
    contributorProperties.forEach((element) => {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const localMetadata = metadata as any
      if (localMetadata[element]) {
        localMetadata[element] = Contributor.Parse(localMetadata[element])
      }
    })
    // constructObjects( metadata, contributorProperties, Contributor.Parse );

    if (metadata.published) {
      metadata.published = new Date(metadata.published)
    }

    if (metadata.modified) {
      metadata.modified = new Date(metadata.modified)
    }

    if (metadata.language) {
      metadata.language = normalizeStringToArray(metadata.language)
    }

    if (metadata.belongsTo) {
      const belongsTo = metadata.belongsTo

      if (belongsTo.collection) {
        belongsTo.collection = Contributor.Parse(belongsTo.collection)
      }

      if (belongsTo.series) {
        belongsTo.series = Contributor.Parse(belongsTo.series)
      }
    }

    return supplementMetadata(metadata, object)
  }
}
