import type {
  ManifestMetadataSourceObjectAnyFormat,
  PublicationMetadata,
} from './types'

// TODO - CYP-1232 think of adding a utility for metadata.json R2 format to Flowpub format migration.
export function supplementFlowpubMetadataWithReadium2FormatMetadata<
  T extends PublicationMetadata
>(metadata: T, metadataSource: ManifestMetadataSourceObjectAnyFormat): T {
  const metadataCopy = { ...metadata }
  if (!metadataCopy.presentation && (metadataSource as any).rendition) {
    // In Readium2 specs https://github.com/readium/webpub-manifest/blob/917c83e798e3eda42b3e9d0dc92f0fef31b16211/schema/extensions/epub/metadata.schema.json#L7
    // Flowpub "presentation" field matches the Readium "rendition".
    metadataCopy.presentation = (metadataSource as any).rendition
  }
  if (!metadataCopy.readingProgression && (metadataSource as any).direction) {
    // According to the code:
    // https://github.com/readium/r2-shared-js/blob/develop/src/models/metadata.ts#L373
    // "readingProgression" might be in the field "direction"
    metadataCopy.readingProgression = (metadataSource as any).direction
  }
  return metadataCopy
}
